/*
 * prog59_rule110.c
 *
 * Re‑implementation of the original program’s observable behaviour.
 * The binary simulates elementary cellular automaton Rule 110.
 *
 * Behaviour:
 *   prog59_rule110 <binary‑string> <steps>
 *
 *   * <binary‑string> – non‑empty string consisting only of ‘0’ and ‘1’,
 *                       length must be at most 60 characters.
 *   * <steps>        – decimal integer, 0 ≤ steps ≤ 200.
 *
 *   If any argument is missing or malformed the program prints
 *   "INVALID_INPUT" (followed by a newline) and exits.
 *
 *   Otherwise it prints the initial row and then <steps> further rows,
 *   each row on its own line, according to Rule 110.  Cells outside the
 *   left/right borders are considered to be 0.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STEPS 200
#define MAX_LEN   60

/* Rule 110 lookup table.
   index = (left << 2) | (center << 1) | right   (0 … 7) */
static const char RULE110[8] = {
    '0', /* 000 */
    '1', /* 001 */
    '1', /* 010 */
    '1', /* 011 */
    '0', /* 100 */
    '1', /* 101 */
    '1', /* 110 */
    '0'  /* 111 */
};

static void print_row(const char *row, size_t len)
{
    fwrite(row, 1, len, stdout);
    putchar('\n');
}

static int is_binary_string(const char *s)
{
    for ( ; *s; ++s )
        if (*s != '0' && *s != '1')
            return 0;
    return 1;
}

static void next_rule110(const char *cur, char *next, size_t len)
{
    for (size_t i = 0; i < len; ++i) {
        char left   = (i == 0)     ? '0' : cur[i - 1];
        char centre = cur[i];
        char right  = (i + 1 == len) ? '0' : cur[i + 1];

        int idx = ((left   - '0') << 2) |
                  ((centre - '0') << 1) |
                  (right  - '0');
        next[i] = RULE110[idx];
    }
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("INVALID_INPUT");
        return 0;
    }

    const char *init_str  = argv[1];
    const char *steps_str = argv[2];

    size_t len = strlen(init_str);
    if (len == 0 || len > MAX_LEN || !is_binary_string(init_str)) {
        puts("INVALID_INPUT");
        return 0;
    }

    char *endptr;
    long steps = strtol(steps_str, &endptr, 10);
    if (endptr == steps_str || *endptr != '\0') {
        puts("INVALID_INPUT");
        return 0;
    }
    if (steps < 0) {
        puts("INVALID_INPUT");
        return 0;
    }
    if (steps > MAX_STEPS)
        steps = MAX_STEPS;

    char *cur  = malloc(len);
    char *next = malloc(len);
    if (!cur || !next) {
        free(cur);
        free(next);
        return 1; /* allocation failure – not expected */
    }

    memcpy(cur, init_str, len);

    /* print the initial row */
    print_row(cur, len);

    for (long gen = 0; gen < steps; ++gen) {
        next_rule110(cur, next, len);
        print_row(next, len);
        char *tmp = cur;
        cur = next;
        next = tmp;
    }

    free(cur);
    free(next);
    return 0;
}
